pattern = r"(Rp[0-9\.,]+Cash62811422404Ayah-)"
matches = list(re.finditer(pattern, text))

for i in range(len(matches)):
    start = matches[i].start()
    end = matches[i+1].start() if i+1 < len(matches) else len(text)
    full_entry = text[start:end]
    header = matches[i].group(1)
    body = full_entry[len(header):]
    
    m_head = re.search(r"Rp([0-9\.,]+)", header)
    h_nominal = float(m_head.group(1).replace(".", "").replace(",", "."))
    
    if "•" in body:
        items = body.split("•")[1:]
        total_items = 0
        item_details = []
        for it in items:
            it = it.strip()
            # find the trailing number
            m_amt = re.search(r"(\d+(?:\.\d+)?)\s*$", it)
            if m_amt:
                amt = float(m_amt.group(1))
                total_items += amt
                item_details.append((it, amt))
            else:
                item_details.append((it, 0))
        
        diff = total_items - h_nominal
        title = body.split("•")[0].strip()
        print(f"Entry {i+1}: Header={h_nominal:,.0f} | Sum={total_items:,.0f} | Diff={diff:,.0f} | Title: {title}")
        for it_text, it_amt in item_details:
            # check suspicious amounts (e.g. 13000 for 2 chickens, 350000 for 1 bks mix vegetable, etc.)
            pass
    else:
        # single
        nums = re.findall(r"\b(\d+)\b", body)
        nums_large = [float(n) for n in nums if float(n) >= 1000]
        title = body.strip()
        if len(nums_large) == 1:
            diff = nums_large[0] - h_nominal
            print(f"Entry {i+1}: Header={h_nominal:,.0f} | BodyVal={nums_large[0]:,.0f} | Diff={diff:,.0f} | Title: {title}")
        else:
            print(f"Entry {i+1}: Header={h_nominal:,.0f} | BodyNums={nums_large} | Title: {title}")
